function loadSystemConfigInputs() {
  if (currentConfigData.CLAUDE_API_KEY) {
    document.getElementById('claude-key').value = currentConfigData.CLAUDE_API_KEY;
    document.getElementById('db-path').value = currentConfigData.WECHAT_DB_PATH;
    document.getElementById('lark-id').value = currentConfigData.LARK_APP_ID || '';
    document.getElementById('lark-secret').value = currentConfigData.LARK_APP_SECRET || '';
    document.getElementById('lark-path').value = currentConfigData.LARK_CLI_PATH || 'lark';
    document.getElementById('openclaw-url').value = currentConfigData.OPENCLAW_API_URL || '';
    document.getElementById('openclaw-token').value = currentConfigData.OPENCLAW_TOKEN || '';
  }
}

// 物理保存 API Key、飞书APPID、APPSECRET 等配置
async function saveEnvConfig() {
  const role = document.getElementById('user-role-select').value;
  const config = {
    CLAUDE_API_KEY: document.getElementById('claude-key').value,
    WECHAT_DB_PATH: document.getElementById('db-path').value,
    LARK_APP_ID: document.getElementById('lark-id').value,
    LARK_APP_SECRET: document.getElementById('lark-secret').value,
    LARK_CLI_PATH: document.getElementById('lark-path').value,
    OPENCLAW_API_URL: document.getElementById('openclaw-url').value,
    OPENCLAW_TOKEN: document.getElementById('openclaw-token').value
  };

  try {
    const res = await fetch(`${GATEWAY_URL}/api/system/config/save`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ config, user_role: role })
    });
    const data = await res.json();
    if (data.success) {
      alert('✅ 环境变量已成功写入本地 .env 文件，网关已实时热加载生效！');
      currentConfigData = config;
    } else {
      alert(`❌ 保存失败：${data.error}`);
    }

